#ifndef OMA_EXEC_QJS_H
#define OMA_EXEC_QJS_H
#include "exec_posix.h"
#include "file_write_posix.h"
static JSValue ox_js_start(JSContext *ctx,JSValueConst self,int argc,JSValueConst *argv){const char *command,*cwd;int32_t timeout=30;int ok;(void)self;if(argc<2)return JS_FALSE;command=JS_ToCString(ctx,argv[0]);cwd=JS_ToCString(ctx,argv[1]);if(argc>2)JS_ToInt32(ctx,&timeout,argv[2]);ok=command&&cwd?ox_start(command,cwd,timeout):0;JS_FreeCString(ctx,command);JS_FreeCString(ctx,cwd);return JS_NewBool(ctx,ok);}
/* Secrets stay in the transport. Scrub the configured key even if a command
 * accidentally prints a private config file before any output reaches JS. */
static JSValue ox_redact(JSContext *ctx,const char *bytes,size_t length){JSValue config=ai_config(ctx),key;const char *token;char *copy=malloc(length+1);size_t n;(void)ctx;if(!copy)return JS_ThrowOutOfMemory(ctx);memcpy(copy,bytes,length);copy[length]=0;
 if(JS_IsException(config)){JSValue e=JS_GetException(ctx);JS_FreeValue(ctx,e);config=JS_NULL;}key=JS_IsObject(config)?JS_GetPropertyStr(ctx,config,"apiKey"):JS_UNDEFINED;token=JS_IsString(key)?JS_ToCString(ctx,key):NULL;
 if(token&&(n=strlen(token))>0){char *p=copy;while((p=strstr(p,token))){memset(p,'*',n);p+=n;}}JS_FreeCString(ctx,token);JS_FreeValue(ctx,key);JS_FreeValue(ctx,config);key=JS_NewStringLen(ctx,copy,length);free(copy);return key;}
static JSValue ox_js_poll(JSContext *ctx,JSValueConst self,int argc,JSValueConst *argv){JSValue r=JS_NewObject(ctx);(void)self;(void)argc;(void)argv;ox_poll();JS_SetPropertyStr(ctx,r,"state",JS_NewString(ctx,ox_state==1?"running":ox_state==3?"cancelled":"done"));JS_SetPropertyStr(ctx,r,"output",ox_redact(ctx,ox_output,ox_length));JS_SetPropertyStr(ctx,r,"exitCode",JS_NewInt32(ctx,ox_code));JS_SetPropertyStr(ctx,r,"error",JS_NewString(ctx,ox_error));JS_SetPropertyStr(ctx,r,"truncated",JS_NewBool(ctx,ox_truncated));return r;}
static JSValue ox_js_cancel(JSContext *ctx,JSValueConst self,int argc,JSValueConst *argv){(void)ctx;(void)self;(void)argc;(void)argv;ox_cancel();return JS_UNDEFINED;}
static JSValue ox_js_redact(JSContext *ctx,JSValueConst self,int argc,JSValueConst *argv){const char *text;size_t n;JSValue result;(void)self;if(!argc)return JS_NewString(ctx,"");text=JS_ToCStringLen(ctx,&n,argv[0]);if(!text)return JS_EXCEPTION;result=ox_redact(ctx,text,n);JS_FreeCString(ctx,text);return result;}
static JSValue ox_js_write(JSContext *ctx,JSValueConst self,int argc,JSValueConst *argv){const char *path,*text;size_t n;oma_write_result written;JSValue result;(void)self;if(argc<2)return JS_ThrowTypeError(ctx,"path and text required");path=JS_ToCString(ctx,argv[0]);text=JS_ToCStringLen(ctx,&n,argv[1]);if(!path||!text){JS_FreeCString(ctx,path);JS_FreeCString(ctx,text);return JS_EXCEPTION;}written=oma_write_file(path,text,n);JS_FreeCString(ctx,path);JS_FreeCString(ctx,text);result=JS_NewObject(ctx);JS_SetPropertyStr(ctx,result,"ok",JS_NewBool(ctx,written.ok));JS_SetPropertyStr(ctx,result,"atomic",JS_NewBool(ctx,written.atomic));JS_SetPropertyStr(ctx,result,"error",JS_NewString(ctx,written.error));return result;}
static int oma_install_exec(JSContext *ctx,JSValueConst global){JSValue api=JS_NewObject(ctx);JS_SetPropertyStr(ctx,api,"redact",JS_NewCFunction(ctx,ox_js_redact,"redact",1));JS_SetPropertyStr(ctx,api,"write",JS_NewCFunction(ctx,ox_js_write,"write",2));JS_SetPropertyStr(ctx,api,"start",JS_NewCFunction(ctx,ox_js_start,"start",3));JS_SetPropertyStr(ctx,api,"poll",JS_NewCFunction(ctx,ox_js_poll,"poll",0));JS_SetPropertyStr(ctx,api,"cancel",JS_NewCFunction(ctx,ox_js_cancel,"cancel",0));return JS_SetPropertyStr(ctx,global,"omaExec",api)>=0;}
#endif
